// Prepare full pipeline request
const body = $input.first().json.body || {};

return {
  json: {
    sources: body.sources || ['apex-jobs', 'insight-global-jobs', 'teksystems-jobs'],
    sync_to_hub: body.sync_to_hub !== false,
    include_insights: body.include_insights !== false,
    locations: body.locations || ['Washington DC', 'Virginia', 'Maryland']
  }
};

// Process pipeline response
const response = $input.first().json;
const request = $('Prepare Request').first().json;

const summary = response.summary || {};

return {
  json: {
    success: response.status === 'completed' || response.status === 'success',
    pipeline: {
      sources_processed: request.sources.length,
      total_scraped: summary.total_scraped || 0,
      unique_jobs: summary.unique || 0,
      valid_jobs: summary.valid || 0,
      synced_to_hub: summary.synced || 0
    },
    duration_seconds: response.duration_seconds || 0,
    errors: response.errors || [],
    message: `Full pipeline completed: ${summary.synced || 0} jobs synced to Hub`,
    timestamp: new Date().toISOString()
  }
};
